#pragma once
#include <cuda_runtime.h>
#include <cublasDx.h>

constexpr int kM = 64, kN = 32, kK = 48;

// C_b = alpha * A_b^T * B_b + beta * C_b, in place on C. A_b is K x M, B_b is K x N, C_b is M x N, all row-major.
void solve(const float* A, const float* B, float* C, float alpha, float beta, int batch, cudaStream_t stream) {
    cublasDxHandle_t handle;
    cublasDxCreate(&handle);

    // Set up the batch GEMM parameters
    cublasDxGemmBatchedParams params;
    cublasDxGemmBatchedParamsInit(&params);

    // Set the matrix dimensions
    params.m = kM;
    params.n = kN;
    params.k = kK;

    // Set the alpha and beta values
    params.alpha = alpha;
    params.beta = beta;

    // Set the matrix layout (row-major)
    params.layout = CUBLAS_LAYOUT_ROW_MAJOR;

    // Set the data type
    params.dataType = CUBLAS_DATA_TYPE_FLOAT;

    // Set the batch size
    params.batchCount = batch;

    // Set the matrix pointers
    params.A = A;
    params.B = B;
    params.C = C;

    // Set the stream
    params.stream = stream;

    // Launch the batched GEMM
    cublasDxGemmBatched(handle, params);

    // Destroy the handle
    cublasDxDestroy(handle);
}

