    cublasDxMatmulDescInit(descD, CUBLASDX_OP_N, CUBLASDX_OP_N, kM, kM, kM);

    // Set up the batch matrix multiplication parameters
    cublasDxMatmulParams_t params;
    cublasDxMatmulParamsInit(&params);
    params.alpha = 1.0f;
    params.beta = 0.0f;

    // Launch the batch matrix multiplication
    cublasDxMatmulBatched(handle, descA, A, descB, B, descC, C, descD, D, params, batch, stream);

    // Destroy the cuBLASDx handle
