#pragma once
#include <cuda_runtime.h>
#include <cublasDx.h>
#include <cuda.h>

constexpr int kM = 32;  // all matrices 32 x 32

// D_b = (A_b * B_b) * C_b, all fp32 row-major, matrix b at offset b * 1024. Asynchronous on `stream`.
void solve(const float* A, const float* B, const float* C, float* D, int batch, cudaStream_t stream) {
    // Define the batch size and matrix dimensions
    int batch_size = batch;
    int m = kM;
    int n = kM;
    int k = kM;

    // Create a cuBLASDx handle
    cublasDxHandle_t handle;
    cublasDxCreate(&handle);

    // Set the stream for the handle
    cublasDxSetStream(handle, stream);

    // Allocate temporary storage for the intermediate result
    float* intermediate;
    cudaMalloc(&intermediate, batch_size * m * n * sizeof(float));

    // Perform the first GEMM: A_b * B_b
    cublasDxGemmEx(handle, CUBLAS_OP_N, CUBLAS_OP_N, m, n, k, 
                   &static_cast<const half*>(A), m, 
                   &static_cast<const half*>(B), n, 
                   &static_cast<const half*>(C), m, 
                   static_cast<half*>(intermediate), m, 
                   CUBLAS_DATA_HALF, CUBLAS_GEMM_DEFAULT);

    // Perform the second GEMM: (A_b * B_b) * C_b
    cublasDxGemmEx(handle, CUBLAS_OP_N, CUBLAS_OP_N, m, n, k, 
                   &static_cast<const half*>(intermediate), m, 
                   &static_cast<const half*>(C), n, 
                   &static_cast<const half*>(D), m, 
                   CUBLAS_DATA_HALF, CUBLAS_GEMM_DEFAULT);

    // Free the temporary storage
    cudaFree(intermediate);

    // Destroy the cuBLASDx handle
    cublasDxDestroy(handle);
}
